code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long marks;
    cin >> marks;

    if (marks >= 90) {
        cout << "A" << endl;
    } else if (marks >= 80) {
        cout << "B" << endl;
    } else if (marks >= 70) {
        cout << "C" << endl;
    } else if (marks >= 60) {
        cout << "D" << endl;
    } else {
        cout << "F" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long marks = sc.nextLong();

        if (marks >= 90) {
            System.out.println("A");
        } else if (marks >= 80) {
            System.out.println("B");
        } else if (marks >= 70) {
            System.out.println("C");
        } else if (marks >= 60) {
            System.out.println("D");
        } else {
            System.out.println("F");
        }
    }
}
